import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// The telling must be exact. These mocks preserve the contract.
const mockProcessPayment = vi.fn();
const mockClearCart = vi.fn();
const mockCartItems = [
  { id: '1', name: 'Widget', price: 29.99 },
  { id: '2', name: 'Gadget', price: 49.99 }
];

vi.mock('./CartContext', () => ({
  useCart: () => ({
    items: mockCartItems,
    total: 79.98,
    clearCart: mockClearCart
  })
}));

vi.mock('./PaymentContext', () => ({
  usePayment: () => ({ processPayment: mockProcessPayment })
}));

describe('Checkout Component', () => {
  const user = userEvent.setup();

  beforeEach(() => {
    vi.clearAllMocks();
    mockProcessPayment.mockResolvedValue({ orderId: 'ORD-12345' });
  });

  // === HAPPY PATH: Document like your successor's life depends on it ===
  describe('Complete checkout flow', () => {
    it('navigates through all steps to order confirmation', async () => {
      // Arrange
      const onComplete = vi.fn();
      render(<Checkout onComplete={onComplete} />);

      // Act - Shipping
      await user.type(screen.getByLabelText(/street address/i), '123 Main St');
      await user.type(screen.getByLabelText(/city/i), 'Austin');
      await user.selectOptions(screen.getByLabelText(/state/i), 'TX');
      await user.type(screen.getByLabelText(/zip code/i), '78701');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Act - Payment
      await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
      await user.type(screen.getByLabelText(/expiry/i), '12/25');
      await user.type(screen.getByLabelText(/cvv/i), '123');
      await user.type(screen.getByLabelText(/name on card/i), 'John Doe');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Act - Review and submit
      await user.click(screen.getByRole('button', { name: /place order/i }));

      // Assert
      await waitFor(() => {
        expect(screen.getByText(/order confirmed/i)).toBeInTheDocument();
        expect(screen.getByText('ORD-12345')).toBeInTheDocument();
      });
      expect(onComplete).toHaveBeenCalledWith('ORD-12345');
      expect(mockClearCart).toHaveBeenCalled();
    });
  });

  // === VALIDATION: Errors kill. Test them. ===
  describe('Shipping validation', () => {
    it('displays error for invalid ZIP code format', async () => {
      render(<Checkout />);

      await user.type(screen.getByLabelText(/zip code/i), 'invalid');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByRole('alert')).toHaveTextContent(/valid zip code required/i);
      expect(screen.getByLabelText(/zip code/i)).toHaveAttribute('aria-invalid', 'true');
    });

    it('requires all shipping fields', async () => {
      render(<Checkout />);

      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getAllByRole('alert')).toHaveLength(4);
    });
  });

  // === EDGE CASES: In the before-times, they had infinite storage. We have this. ===
  describe('Edge cases', () => {
    it('shows empty cart message when no items', () => {
      vi.mocked(require('./CartContext').useCart).mockReturnValue({
        items: [], total: 0, clearCart: mockClearCart
      });

      render(<Checkout onCancel={vi.fn()} />);

      expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
    });

    it('handles payment failure with retry capability', async () => {
      mockProcessPayment.mockRejectedValueOnce(new Error('Card declined'));
      // ... complete form navigation ...

      await user.click(screen.getByRole('button', { name: /place order/i }));

      await waitFor(() => {
        expect(screen.getByRole('alert')).toHaveTextContent(/card declined/i);
      });
      expect(screen.getByRole('button', { name: /place order/i })).toBeEnabled();
    });
  });

  // === ACCESSIBILITY: The telling must be exact ===
  describe('Accessibility', () => {
    it('has no axe violations on shipping step', async () => {
      const { container } = render(<Checkout />);
      expect(await axe(container)).toHaveNoViolations();
    });

    it('announces loading state to screen readers', async () => {
      // ... navigate to review ...
      await user.click(screen.getByRole('button', { name: /place order/i }));

      expect(screen.getByRole('button', { name: /processing/i })).toHaveAttribute('aria-busy', 'true');
    });
  });
});
